/* CastFltPsgMapper.updateUserFltPsg */
UPDATE PMOWN.TN_PM_SMLT_USER_FLT_PSG
SET ADJ_TYPE_CD = #{adjTypeCd},
    ADJ_RT = #{adjRate},
    LAST_MDFR_ID = #{loginUserId},
    LAST_MDFR_IP_ADDR = #{loginIpAddr},
    LAST_MDFCN_DT = CURRENT_TIMESTAMP
WHERE 1 = 1
AND SMLT_ID = #{smltId}
AND TMNL_ID = #{fcltTmnlId}

